sections.body:
resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "app" {
  vpc_id     = aws_vpc.main.id      # référence -> dépendance implicite
  cidr_block = "10.0.1.0/24"
}

# Attributs calculés : disponibles APRÈS création (id, arn, adresse IP...)
# On les référence ; Terraform ordonne la création en conséquence.

# Renommer/déplacer une ressource sans la détruire
moved {
  from = aws_instance.web
  to   = aws_instance.frontend
}
resource "aws_instance" "frontend" { /* ... */ }

# Retirer une ressource de Terraform SANS la détruire (déclaratif)
removed {
  from = aws_s3_bucket.legacy
  lifecycle { destroy = false }   # on cesse de la gérer, l'objet reste
}

resource "aws_instance" "web" {
  # ...
  lifecycle {
    postcondition {
      condition     = self.public_ip != ""
      error_message = "L'instance doit avoir une IP publique."
    }
    replace_triggered_by = [aws_launch_template.web.latest_version]
  }
}

resource "aws_db_instance" "main" {
  # ...
  timeouts {
    create = "60m"      # une grosse base peut être longue à créer
    delete = "30m"
  }
}
